// Modelo simplificado de almacen.ts (reloj virtual, sin timers reales).
// Regla: los cambios se juntan y se escriben 400 ms después del primero, o en el acto al pasar a segundo plano.
const ESPERA = 400;
function escenario(nombre, eventos) {
  let pendientes = {};
  let vence = null;
  const disco = {};
  const escribir = (t, por) => {
    const claves = Object.keys(pendientes);
    if (!claves.length) return;
    claves.forEach((k) => (disco[k] = pendientes[k]));
    console.log('t=' + t + ' ms: se escriben ' + claves.length + ' cambio(s) (' + por + ')');
    pendientes = {};
    vence = null;
  };
  console.log('--- ' + nombre);
  for (const e of eventos) {
    if (vence !== null && e.t >= vence) escribir(vence, 'pasaron 400 ms');
    if (e.que === 'cambio') {
      pendientes[e.clave] = e.valor;
      if (vence === null) vence = e.t + ESPERA;
      console.log('t=' + e.t + ' ms: cambio ' + e.clave + '=' + e.valor + ' (queda en memoria)');
    } else if (e.que === 'segundo plano') {
      escribir(e.t, 'la app pasó a segundo plano');
    } else if (e.que === 'muerte') {
      console.log('t=' + e.t + ' ms: el proceso muere con ' + Object.keys(pendientes).length + ' cambio(s) sin escribir');
      pendientes = {};
      vence = null;
    }
  }
  if (vence !== null) escribir(vence, 'pasaron 400 ms');
  console.log('en disco: ' + JSON.stringify(disco));
}
escenario('A: tres cambios seguidos y nada más', [
  { t: 0, que: 'cambio', clave: 'talentos', valor: 10 },
  { t: 100, que: 'cambio', clave: 'racha', valor: 4 },
  { t: 250, que: 'cambio', clave: 'leccion', valor: 'ok' },
]);
escenario('B: un cambio y el proceso muere a los 200 ms', [
  { t: 0, que: 'cambio', clave: 'talentos', valor: 25 },
  { t: 200, que: 'muerte' },
]);
escenario('C: un cambio y la persona sale de la app a los 200 ms', [
  { t: 0, que: 'cambio', clave: 'talentos', valor: 25 },
  { t: 200, que: 'segundo plano' },
  { t: 5000, que: 'muerte' },
]);
